svg.script:
(() => {
  const gear = document.getElementById('settings-icon');
  if (!gear) return;
  let timer;
  const spin = () => {
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    gear.classList.remove('spin');
    void gear.getBoundingClientRect();
    gear.classList.add('spin');
    clearTimeout(timer);
    timer = setTimeout(() => gear.classList.remove('spin'), 420);
  };
  gear.style.cursor = 'pointer';
  gear.addEventListener('click', spin);
  gear.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); spin(); } });
  gear.setAttribute('tabindex', '0');
  gear.setAttribute('role', 'button');
})();
